return "    #解锁关卡一天\n    buy_mode_temporarily 10700 {\n        request {\n            mode 0 : integer #关卡id\n        }\n        response {\n            result 0 : integer # 1 成功 2 失败，已经解锁 3 失败，钻石不足\n        }\n    }\n    #获取重置的关卡信息\n    get_reset_levelmode 10701 {\n        response {\n            result 0 : integer # 1 成功 2 失败\n            mode 1 : *modeconfig\n        }\n    }\n    # 获取指定modetype的关卡数据\n    get_levelmode_by_modetype 10702 {\n        request {\n            modetypes 0 : *integer\n        }\n        response {\n            mode 0 : *modeconfig\n        }\n    }\n"
